#include <iostream>
#include <vector>
#include <utility>
struct Batch {std::vector<int> values;};
int main(){int n;if(!(std::cin>>n)||n<0||n>20){std::cout<<"invalid\n";return 0;}Batch a;
 for(int i=0;i<n;++i){int x;if(!(std::cin>>x)||x< -100||x>100){std::cout<<"invalid\n";return 0;}a.values.push_back(x);}
 std::cin>>std::ws;if(!std::cin.eof()){std::cout<<"invalid\n";return 0;}
 Batch b=a;for(int& x:b.values)++x;Batch c=std::move(a);a.values.assign(1,42);
 int original=0,changed=0;for(int x:c.values)original+=x;for(int x:b.values)changed+=x;
 std::cout<<original<<' '<<changed<<' '<<a.values[0]<<'\n';}
